cd "/c/Users/USER/Downloads/agent-test/vibe/runs/sudoku_haiku-5-5_r5/work" && node -e '
const fs=require("fs"),vm=require("vm");
const html=fs.readFileSync("index.html","utf8");
const js=html.split("<script>")[1].split("</script>")[0];
const mk=()=>{const o={classList:{add(){},remove(){},contains(){return false}},dataset:{},setAttribute(){},addEventListener(){},appendChild(){},focus(){},select(){},style:{}};return o;};
const ctx={console,document:{getElementById:()=>mk(),createElement:()=>mk()}};
vm.createContext(ctx);
vm.runInContext(js+"\n;globalThis.gen=generatePuzzle;globalThis.cs=countSolutions;",ctx);
const t0=Date.now();let givens=[];
for(let k=0;k<30;k++){
  const {puzzle,solution}=ctx.gen();
  const p=puzzle.slice(); const n=ctx.cs(p.slice(),2);
  // verify solution valid & matches givens
  let ok=n===1;
  for(let i=0;i<81;i++){ if(puzzle[i]&&puzzle[i]!==solution[i]) ok=false; }
  for(let r=0;r<9;r++){const s=new Set();for(let c=0;c<9;c++)s.add(solution[r*9+c]);if(s.size!==9)ok=false;}
  if(!ok){console.log("FAIL at",k,n);process.exit(1);}
  givens.push(puzzle.filter(x=>x).length);
}
console.log("30 puzzles OK, unique; givens range",Math.min(...givens),Math.max(...givens),"time ms",Date.now()-t0);
'

